import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Star, Plus, MessageSquare, ThumbsUp, ThumbsDown, Clock, CheckCircle, XCircle } from 'lucide-react';
import { reviewService } from '../services/api';
import { Card, Button, Input, PageHeader, EmptyState, StatusBadge } from '../components/UI';
import toast from 'react-hot-toast';

export default function ReviewPage() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [reviews, setReviews] = useState([]);
  const [showAddReview, setShowAddReview] = useState(false);
  const [reviewForm, setReviewForm] = useState({
    appointmentId: '',
    providerId: '',
    rating: 5,
    comment: '',
    title: '',
  });
  const [errors, setErrors] = useState({});

  useEffect(() => {
    fetchReviews();
  }, []);

  async function fetchReviews() {
    try {
      setLoading(true);
      const userStr = localStorage.getItem('medibook_user');
      if (!userStr) {
        navigate('/login');
        return;
      }

      const user = JSON.parse(userStr);
      const response = await reviewService.getReviewsByPatient(user.userId || 'patient-001');
      setReviews(response.data || []);
    } catch (error) {
      console.error('Failed to fetch reviews:', error);
      toast.error('Failed to load reviews');
    } finally {
      setLoading(false);
    }
  }

  async function handleReviewSubmit(e) {
    e.preventDefault();
    if (!validateReviewForm()) return;

    try {
      setLoading(true);
      const userStr = localStorage.getItem('medibook_user');
      const user = JSON.parse(userStr);

      const reviewData = {
        appointmentId: reviewForm.appointmentId,
        providerId: reviewForm.providerId,
        patientId: user.userId || 'patient-001',
        rating: parseInt(reviewForm.rating),
        title: reviewForm.title,
        comment: reviewForm.comment,
        reviewDate: new Date().toISOString(),
        isVerified: false,
      };

      const response = await reviewService.createReview(reviewData);
      toast.success('Review submitted successfully!');
      setShowAddReview(false);
      setReviewForm({
        appointmentId: '',
        providerId: '',
        rating: 5,
        comment: '',
        title: '',
      });
      fetchReviews();
    } catch (error) {
      console.error('Review submission failed:', error);
      toast.error('Failed to submit review');
    } finally {
      setLoading(false);
    }
  }

  function validateReviewForm() {
    const e = {};
    if (!reviewForm.appointmentId.trim()) e.appointmentId = 'Appointment ID is required';
    if (!reviewForm.providerId.trim()) e.providerId = 'Provider ID is required';
    if (!reviewForm.title.trim()) e.title = 'Review title is required';
    if (!reviewForm.comment.trim()) e.comment = 'Review comment is required';
    if (reviewForm.rating < 1 || reviewForm.rating > 5) e.rating = 'Rating must be between 1 and 5';

    setErrors(e);
    return Object.keys(e).length === 0;
  }

  function renderStars(rating, interactive = false) {
    return (
      <div style={{ display: 'flex', gap: '4px' }}>
        {[1, 2, 3, 4, 5].map((star) => (
          <Star
            key={star}
            size={interactive ? 20 : 16}
            style={{
              color: star <= rating ? '#fbbf24' : '#d1d5db',
              cursor: interactive ? 'pointer' : 'default',
              transition: 'color 0.2s',
            }}
            fill={star <= rating}
            onClick={interactive ? () => setReviewForm({ ...reviewForm, rating: star }) : undefined}
          />
        ))}
      </div>
    );
  }

  function getStatusColor(status) {
    switch (status) {
      case 'Verified': return '#10b981';
      case 'Pending': return '#f59e0b';
      case 'Rejected': return '#ef4444';
      default: return '#64748b';
    }
  }

  function getStatusIcon(status) {
    switch (status) {
      case 'Verified': return CheckCircle;
      case 'Pending': return Clock;
      case 'Rejected': return XCircle;
      default: return MessageSquare;
    }
  }

  if (loading && reviews.length === 0) {
    return (
      <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '400px' }}>
        <div>Loading reviews...</div>
      </div>
    );
  }

  return (
    <div style={{ padding: '24px', backgroundColor: '#f8fafc', minHeight: '100vh' }}>
      <PageHeader
        title="Review Management"
        subtitle="Manage your reviews and feedback"
        actions={
          <Button onClick={() => setShowAddReview(true)}>
            <Plus size={16} style={{ marginRight: 6 }} />
            Write Review
          </Button>
        }
      />

      {/* Review History */}
      <Card style={{ padding: '24px', marginBottom: '24px' }}>
        <div style={{ display: 'flex', alignItems: 'center', marginBottom: '20px' }}>
          <MessageSquare size={20} style={{ marginRight: 8 }} />
          <h3 style={{ fontSize: '1.25rem', fontWeight: 600, margin: 0 }}>Your Reviews</h3>
        </div>

        {reviews.length === 0 ? (
          <EmptyState
            icon={Star}
            title="No Reviews Yet"
            description="You haven't written any reviews yet. Share your experience with providers."
          />
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
            {reviews.map((review) => {
              const StatusIcon = getStatusIcon(review.isVerified ? 'Verified' : 'Pending');
              return (
                <div
                  key={review.reviewId}
                  style={{
                    padding: '20px',
                    border: '1px solid #e2e8f0',
                    borderRadius: '12px',
                    backgroundColor: '#fff',
                  }}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '12px' }}>
                    <div style={{ flex: 1 }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '4px' }}>
                        <h4 style={{ fontSize: '1rem', fontWeight: 600, margin: 0 }}>
                          {review.title}
                        </h4>
                        <StatusBadge status={review.isVerified ? 'Verified' : 'Pending'} />
                      </div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '8px' }}>
                        {renderStars(review.rating)}
                        <span style={{ fontSize: '0.9rem', color: '#64748b', fontWeight: 600 }}>
                          {review.rating}.0
                        </span>
                      </div>
                      <div style={{ fontSize: '0.85rem', color: '#64748b', marginBottom: '4px' }}>
                        Provider ID: {review.providerId?.slice(0, 8)}…
                      </div>
                      <div style={{ fontSize: '0.85rem', color: '#64748b' }}>
                        {new Date(review.reviewDate || Date.now()).toLocaleDateString()}
                      </div>
                    </div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                      <StatusIcon size={16} color={getStatusColor(review.isVerified ? 'Verified' : 'Pending')} />
                      <span style={{ fontSize: '0.85rem', color: getStatusColor(review.isVerified ? 'Verified' : 'Pending') }}>
                        {review.isVerified ? 'Verified' : 'Pending'}
                      </span>
                    </div>
                  </div>
                  <div style={{ marginTop: '12px', paddingTop: '12px', borderTop: '1px solid #e2e8f0' }}>
                    <p style={{ fontSize: '0.9rem', color: '#374151', lineHeight: 1.5, margin: 0 }}>
                      {review.comment}
                    </p>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </Card>

      {/* Add Review Modal */}
      {showAddReview && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: 'rgba(0, 0, 0, 0.5)',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          zIndex: 1000,
        }}>
          <Card style={{ padding: '32px', width: '100%', maxWidth: '600px', maxHeight: '90vh', overflowY: 'auto' }}>
            <div style={{ display: 'flex', alignItems: 'center', marginBottom: '24px' }}>
              <Star size={24} style={{ marginRight: 12 }} />
              <h3 style={{ fontSize: '1.5rem', fontWeight: 600, margin: 0 }}>Write a Review</h3>
            </div>

            <form onSubmit={handleReviewSubmit}>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
                <Input
                  label="Appointment ID"
                  value={reviewForm.appointmentId}
                  onChange={(e) => setReviewForm({ ...reviewForm, appointmentId: e.target.value })}
                  error={errors.appointmentId}
                  placeholder="Enter appointment ID"
                />

                <Input
                  label="Provider ID"
                  value={reviewForm.providerId}
                  onChange={(e) => setReviewForm({ ...reviewForm, providerId: e.target.value })}
                  error={errors.providerId}
                  placeholder="Enter provider ID"
                />

                <div>
                  <label style={{ fontSize: '0.82rem', fontWeight: 500, color: 'var(--text-muted)', marginBottom: '8px', display: 'block' }}>
                    Rating
                  </label>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                    {renderStars(reviewForm.rating, true)}
                    <span style={{ fontSize: '0.9rem', color: '#64748b', fontWeight: 600 }}>
                      {reviewForm.rating}.0
                    </span>
                  </div>
                  {errors.rating && <span style={{ fontSize: '0.78rem', color: '#ef4444' }}>{errors.rating}</span>}
                </div>

                <Input
                  label="Review Title"
                  value={reviewForm.title}
                  onChange={(e) => setReviewForm({ ...reviewForm, title: e.target.value })}
                  error={errors.title}
                  placeholder="Summarize your experience"
                />

                <div>
                  <label style={{ fontSize: '0.82rem', fontWeight: 500, color: 'var(--text-muted)', marginBottom: '5px', display: 'block' }}>
                    Review Comment
                  </label>
                  <textarea
                    value={reviewForm.comment}
                    onChange={(e) => setReviewForm({ ...reviewForm, comment: e.target.value })}
                    error={errors.comment}
                    placeholder="Share your detailed experience..."
                    rows={4}
                    style={{
                      width: '100%',
                      padding: '12px 14px',
                      borderRadius: 10,
                      border: `1px solid ${errors.comment ? '#ef4444' : 'var(--border)'}`,
                      fontFamily: 'var(--font-body)',
                      fontSize: '0.92rem',
                      resize: 'vertical',
                      outline: 'none',
                      color: 'var(--text)',
                    }}
                  />
                  {errors.comment && <span style={{ fontSize: '0.78rem', color: '#ef4444' }}>{errors.comment}</span>}
                </div>

                <div style={{ display: 'flex', gap: '12px', marginTop: '8px' }}>
                  <Button type="submit" disabled={loading}>
                    {loading ? 'Submitting...' : 'Submit Review'}
                  </Button>
                  <Button
                    type="button"
                    variant="ghost"
                    onClick={() => {
                      setShowAddReview(false);
                      setReviewForm({
                        appointmentId: '',
                        providerId: '',
                        rating: 5,
                        comment: '',
                        title: '',
                      });
                      setErrors({});
                    }}
                  >
                    Cancel
                  </Button>
                </div>
              </div>
            </form>
          </Card>
        </div>
      )}
    </div>
  );
}
